#!/bin/sh
# Waits for the config generated by the gateway (from .env / config/users.yml) and runs telemt.
# telemt listens on 127.0.0.1:${MTPROXY_INTERNAL_PORT} only; the gateway forwards FakeTLS
# clients from :443 to it with a PROXY v2 header.
#
# telemt hot-reloads only part of its config (e.g. use_middle_proxy / unknown_sni_action need a
# restart), so this script restarts telemt whenever the gateway rewrites config.toml.
set -e
CONF=/etc/telemt/config.toml

i=0
while [ ! -f "$CONF" ] && [ ! -f /etc/telemt/DISABLED ]; do
  i=$((i+1))
  [ $i -gt 120 ] && { echo "telemt: config not generated by gateway after 120s"; exit 1; }
  sleep 1
done

if [ -f /etc/telemt/DISABLED ]; then
  echo "telemt: MTProxy disabled ($(cat /etc/telemt/DISABLED)). Idle."
  # stay idle but react to the config appearing later (gateway restart with users added)
  while [ -f /etc/telemt/DISABLED ]; do sleep 30; done
fi

PID=""
stop() {
  [ -n "$PID" ] && kill "$PID" 2>/dev/null && wait "$PID" 2>/dev/null
  exit 0
}
trap stop TERM INT

sum() { md5sum "$CONF" 2>/dev/null | cut -d' ' -f1; }
# MTPROXY_UPSTREAM_IFACE (gateway -> [[upstreams]] interface = "...", e.g. the WireGuard uplink
# sgup0): telemt's outgoing connections need that interface, wait for it before (re)starting.
wait_iface() {
  IF=$(sed -n 's/^interface = "\(.*\)"$/\1/p' "$CONF" | head -n1)
  [ -n "$IF" ] || return 0
  [ -e "/sys/class/net/$IF" ] && return 0
  echo "telemt: waiting for upstream interface $IF (wireguard container, WG_MODE=uplink)"
  while [ ! -e "/sys/class/net/$IF" ]; do sleep 2; done
  sleep 2
  echo "telemt: interface $IF is up"
}

while true; do
  wait_iface
  CUR=$(sum)
  echo "telemt: starting with $CONF"
  telemt run "$CONF" --data-path /etc/telemt &
  PID=$!
  while kill -0 "$PID" 2>/dev/null; do
    sleep 5
    NEW=$(sum)
    if [ -n "$NEW" ] && [ "$NEW" != "$CUR" ]; then
      echo "telemt: config.toml changed - restarting telemt"
      kill "$PID" 2>/dev/null || true
      wait "$PID" 2>/dev/null || true
      break
    fi
  done
  wait "$PID" 2>/dev/null || { echo "telemt: exited, restarting in 3s"; sleep 3; }
  PID=""
done
